import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

custom_kernel_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void lower_tri_matmul_kernel(const float* A, const float* B, float* C, int N) {
    int linear_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = (N * (N + 1)) / 2;

    if (linear_idx >= total_elements) return;

    // Convert linear index to (i,j) in lower triangle
    int i = (sqrt(8 * linear_idx + 1) - 1) / 2;
    int j = linear_idx - (i * (i + 1)) / 2;

    if (i >= N || j > i) return;

    float sum = 0.0f;
    for(int k = j; k <= i; k++) {
        sum += A[i * N + k] * B[k * N + j];
    }
    C[i * N + j] = sum;
}

torch::Tensor lower_tri_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    torch::Tensor C = torch::zeros({N, N}, A.options());

    int total_elements = (N * (N + 1)) / 2;
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;

    lower_tri_matmul_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

cpp_wrapper = "torch::Tensor lower_tri_matmul_cuda(torch::Tensor A, torch::Tensor B);"

tri_mm_extension = load_inline(
    name='tri_mm_extension',
    cpp_sources=cpp_wrapper,
    cuda_sources=custom_kernel_code,
    functions=['lower_tri_matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return tri_mm_extension.lower_tri_matmul_cuda(A, B)
